const cfg = $('Config').first().json;

function safeNodeJson(name) {
  try {
    return $(name).first()?.json ?? {};
  } catch (error) {
    return {};
  }
}

function toNumber(value) {
  const num = Number(value ?? 0);
  return Number.isFinite(num) ? num : 0;
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  if (Array.isArray(value.data)) return value.data;
  if (Array.isArray(value.items)) return value.items;
  if (Array.isArray(value.points)) return value.points;
  if (Array.isArray(value.rows)) return value.rows;
  if (Array.isArray(value.results)) return value.results;
  return [];
}

function money(value) {
  return '$' + toNumber(value).toFixed(2);
}

function percent(value) {
  return toNumber(value).toFixed(1) + '%';
}

function normalizeSales(raw) {
  const arr = asArray(raw);
  if (!arr.length && raw && typeof raw === 'object') {
    const direct = toNumber(raw.total ?? raw.totalSales ?? raw.amount ?? raw.sales);
    if (direct > 0) return direct;
  }
  return arr.reduce((sum, point) => sum + toNumber(point.total ?? point.totalSales ?? point.amount ?? point.sales), 0);
}

function normalizeGoals(raw) {
  const items = asArray(raw.items ?? raw);
  return items.map((item) => ({
    softwareName: item.softwareName ?? item.productName ?? item.name ?? 'Producto',
    achieved: Boolean(item.achieved ?? item.completed ?? false),
    variance: toNumber(item.variance ?? item.remaining ?? item.gap ?? 0),
    soldAmount: toNumber(item.soldAmount ?? item.totalSales ?? item.amount ?? 0),
    soldUnits: toNumber(item.soldUnits ?? item.unitsSold ?? item.quantity ?? 0),
  }));
}

function normalizeInventory(raw) {
  return asArray(raw).map((item) => ({
    name: item.name ?? item.softwareName ?? item.title ?? item.productName ?? 'Producto sin nombre',
    stock: toNumber(item.stock ?? item.available ?? 0),
  }));
}

function normalizeExpenses(raw, todayStr) {
  const items = asArray(raw);
  if (items.length) {
    return items.map((item) => ({
      name: item.name ?? item.vendor ?? item.concept ?? item.title ?? 'Gasto',
      amount: toNumber(item.amount ?? item.total ?? item.balance ?? 0),
      dueDate: String(item.dueDate ?? item.date ?? todayStr).slice(0, 10),
      status: (item.status ?? 'pending').toLowerCase(),
    }));
  }
  return [
    { name: 'Internet', amount: 50, dueDate: todayStr, status: 'pending' },
    { name: 'Hosting', amount: 20, dueDate: todayStr, status: 'pending' },
    { name: 'Publicidad', amount: 100, dueDate: todayStr, status: 'pending' }
  ];
}

function normalizeAR(raw) {
  return asArray(raw).map((item) => ({
    client: item.client ?? item.customer ?? item.clientName ?? 'Cliente',
    amount: toNumber(item.amount ?? item.balance ?? item.total ?? 0),
    dueDate: String(item.dueDate ?? item.date ?? '').slice(0, 10),
    status: (item.status ?? 'overdue').toLowerCase(),
  }));
}

function addDays(date, days) {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next;
}

function formatDateISO(date) {
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}

const todayReport = safeNodeJson('Get Today Sales');
const monthReport = safeNodeJson('Get Month Sales');
const goalsReport = safeNodeJson('Get Goals Report');
const inventoryAlerts = safeNodeJson('Get Inventory Alerts');
const arReport = safeNodeJson('Get AR Overdue');
const expensesReport = safeNodeJson('Get Expenses Report');

const todaySales = normalizeSales(todayReport);
const monthSales = normalizeSales(monthReport);
const monthlyGoal = toNumber(cfg.monthlyGoal);

const remainingToGoal = Math.max(monthlyGoal - monthSales, 0);
const progressPercent = monthlyGoal > 0 ? (monthSales / monthlyGoal) * 100 : 0;

const today = new Date(cfg.todayDate + 'T00:00:00');
const dayOfMonth = today.getDate();
const endOfMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0);
const daysInMonth = endOfMonth.getDate();
const expectedPercentToday = daysInMonth > 0 ? (dayOfMonth / daysInMonth) * 100 : 0;
const isBehindTarget = progressPercent < expectedPercentToday;
const projectedClose = dayOfMonth > 0 ? (monthSales / dayOfMonth) * daysInMonth : monthSales;

const goals = normalizeGoals(goalsReport);
const topProducts = goals
  .sort((a, b) => (b.soldAmount || b.soldUnits) - (a.soldAmount || a.soldUnits))
  .slice(0, 5)
  .map((item) => ({
    name: item.softwareName,
    soldAmount: item.soldAmount,
    soldUnits: item.soldUnits,
    variance: item.variance,
  }));

const productsToPush = goals
  .filter((item) => !item.achieved)
  .sort((a, b) => a.variance - b.variance)
  .slice(0, 5)
  .map((item) => item.softwareName);

const zeroSalesProducts = normalizeInventory(inventoryAlerts).slice(0, 5).map((item) => item.name);

const todayStr = formatDateISO(today);
const nextThreeStr = formatDateISO(addDays(today, 3));

const expenses = normalizeExpenses(expensesReport, todayStr);
const pendingExpenses = expenses.filter((expense) => expense.status !== 'paid');
const dueToday = pendingExpenses.filter((expense) => expense.dueDate === todayStr);
const overdueExpenses = pendingExpenses.filter((expense) => expense.dueDate < todayStr);
const nextExpenses = pendingExpenses.filter((expense) => expense.dueDate > todayStr && expense.dueDate <= nextThreeStr);
const totalExpensesToday = dueToday.reduce((sum, expense) => sum + expense.amount, 0);
const totalExpensesUpcoming = nextExpenses.reduce((sum, expense) => sum + expense.amount, 0);

const overdueAR = normalizeAR(arReport).filter((item) => !item.status.includes('paid'));
const overdueARTotal = overdueAR.reduce((sum, item) => sum + item.amount, 0);
const overdueARLines = overdueAR.slice(0, 5).map((item) => `- ${item.client}: ${money(item.amount)}`);

let statusEmoji = '✅';
let priorityMessage = 'Vamos en ritmo. Mantener conversion, seguimiento y empuje de productos clave.';
if (overdueExpenses.length > 0 || overdueAR.length > 0) {
  statusEmoji = '🚨';
  priorityMessage = 'Prioridad total en liquidez: hay obligaciones vencidas o cartera critica que requieren accion inmediata.';
} else if (dueToday.length > 0) {
  statusEmoji = '⚠️';
  priorityMessage = 'Hoy debemos proteger caja, cubrir pagos importantes y sostener el ritmo comercial.';
} else if (todaySales === 0 || isBehindTarget) {
  statusEmoji = '⚠️';
  priorityMessage = 'Hoy debemos priorizar cierre comercial, seguimiento y empuje de productos para recuperar la meta.';
}

const todayLines = dueToday.length ? dueToday.map((item) => `- ${item.name}: ${money(item.amount)}`).join('\n') : 'Sin pagos hoy';
const overdueLines = overdueExpenses.length ? overdueExpenses.map((item) => `- ${item.name}: ${money(item.amount)}`).join('\n') : 'Sin vencidos';
const upcomingLines = nextExpenses.length ? nextExpenses.map((item) => `- ${item.name}: ${money(item.amount)} (${item.dueDate})`).join('\n') : 'Sin pagos proximos';
const topLines = topProducts.length
  ? topProducts.map((item, index) => `${index + 1}. ${item.name} - ${item.soldUnits || 0} ventas - ${money(item.soldAmount)}`).join('\n')
  : 'Sin datos de productos';
const pushLines = productsToPush.length ? productsToPush.map((item, index) => `${index + 1}. ${item}`).join('\n') : 'Sin productos a empujar';
const zeroLines = zeroSalesProducts.length ? zeroSalesProducts.map((item) => `- ${item}`).join('\n') : 'Sin productos sin movimiento';
const arLines = overdueARLines.length ? overdueARLines.join('\n') : 'Sin cartera vencida';

const message =
`📊 <b>REPORTE EJECUTIVO DISMAL</b>

Buenos dias.

🎯 <b>Meta mensual:</b> ${money(monthlyGoal)}
💰 <b>Venta acumulada:</b> ${money(monthSales)}
🧾 <b>Venta hoy:</b> ${money(todaySales)}
✅ <b>Avance:</b> ${percent(progressPercent)}
📈 <b>Ritmo esperado:</b> ${percent(expectedPercentToday)}
⚠️ <b>Faltante:</b> ${money(remainingToGoal)}
🔮 <b>Proyeccion:</b> ${money(projectedClose)}

💸 <b>PAGOS IMPORTANTES</b>
<b>Hoy:</b>
${todayLines}

<b>Vencidos:</b>
${overdueLines}

<b>Proximos 3 dias:</b>
${upcomingLines}

💳 <b>CARTERA VENCIDA</b>
${arLines}
<b>Total vencido:</b> ${money(overdueARTotal)}

🔥 <b>Top productos</b>
${topLines}

🚀 <b>Productos a empujar</b>
${pushLines}

🧊 <b>Sin movimiento</b>
${zeroLines}

${statusEmoji} <b>PRIORIDAD DEL DIA</b>
${priorityMessage}`;

return [{
  json: {
    message,
    todaySales,
    monthSales,
    monthlyGoal,
    remainingToGoal,
    progressPercent,
    expectedPercentToday,
    isBehindTarget,
    projectedClose,
    totalExpensesToday,
    totalExpensesUpcoming,
    overdueExpensesCount: overdueExpenses.length,
    dueTodayCount: dueToday.length,
    nextExpensesCount: nextExpenses.length,
    overdueARTotal,
    overdueARCount: overdueAR.length,
    topProducts,
    productsToPush,
    zeroSalesProducts,
  }
}];
